# benchmark/lib/scale_table.R
# Parametric generator for the shared peak table used in the head-to-head
# scaling sweeps. Both engines receive the SAME generated file at each grid
# point, so timings are on identical input.
#
# Two modes:
#   * make_scaled_table(): purely synthetic (extends the make_bc_data fixture
#     pattern). Used when no real peak table is available.
#   * make_scaled_from_real(): bootstrap rows/features from the real
#     PeakForgeR-derived shared_table.csv with small multiplicative jitter, so
#     duplicated samples are not byte-identical (avoids degenerate RSD == 0).
#
# Output schema is the canonical BENCH schema (see config.R):
#   sample_name, sample_type, batch, run_order, <feature_1>, ... <feature_k>

# Lay out QC + sample rows across n_batches, with contiguous per-batch
# run_order blocks (bc_validate_input requires non-overlapping run_order
# ranges per batch) and >= n_qc_per_batch QC injections per batch.
.bench_layout <- function(n_samples, n_batches, qc_fraction = 0.1,
                          min_qc_per_batch = 2L) {
  per_batch <- rep(n_samples %/% n_batches, n_batches)
  rem <- n_samples - sum(per_batch)
  if (rem > 0) per_batch[seq_len(rem)] <- per_batch[seq_len(rem)] + 1L

  batch <- character(0)
  sample_type <- character(0)
  for (b in seq_len(n_batches)) {
    nb <- per_batch[b]
    n_qc <- max(min_qc_per_batch, round(nb * qc_fraction))
    n_qc <- min(n_qc, nb)
    # Spread QC injections evenly through the batch (incl. first & last).
    qc_pos <- unique(round(seq(1, nb, length.out = n_qc)))
    types <- rep("sample", nb)
    types[qc_pos] <- "qc"
    batch <- c(batch, rep(paste0("plate", b), nb))
    sample_type <- c(sample_type, types)
  }
  data.frame(
    batch = batch,
    sample_type = sample_type,
    run_order = seq_len(length(batch)),
    stringsAsFactors = FALSE
  )
}

#' Fully synthetic scaled table.
#' @param n_samples,n_features,n_batches grid point dimensions
#' @param seed RNG seed (kept fixed per grid point for reproducibility)
make_scaled_table <- function(n_samples = 500, n_features = 200,
                              n_batches = 2, seed = 42) {
  withr::with_seed(seed, {
    layout <- .bench_layout(n_samples, n_batches)
    n <- nrow(layout)
    # Per-feature baseline + per-batch drift to make batch correction meaningful.
    feat_names <- sprintf("feat_%04d", seq_len(n_features))
    mat <- matrix(0, nrow = n, ncol = n_features,
                  dimnames = list(NULL, feat_names))
    batch_idx <- as.integer(factor(layout$batch))
    for (j in seq_len(n_features)) {
      base <- stats::rlnorm(1, meanlog = log(1e5), sdlog = 1)
      drift <- 1 + 0.15 * (batch_idx - mean(batch_idx))     # multiplicative batch shift
      trend <- 1 + 0.0005 * layout$run_order                # within-run signal drift
      noise <- stats::rnorm(n, mean = 1, sd = 0.08)
      mat[, j] <- base * drift * trend * pmax(noise, 0.01)
    }
    df <- cbind(
      data.frame(sample_name = sprintf("S%05d", seq_len(n)),
                 sample_type = layout$sample_type,
                 batch = layout$batch,
                 run_order = layout$run_order,
                 stringsAsFactors = FALSE),
      as.data.frame(mat, check.names = FALSE)
    )
    df
  })
}

#' Bootstrap a scaled table from the real shared_table.csv.
#' Rows are resampled (with replacement when scaling up) and given small
#' multiplicative jitter; features are subsampled or tiled (with _dupN
#' suffixes) to hit n_features. QC/sample composition and per-batch run_order
#' blocks are regenerated by .bench_layout so the structure is valid.
make_scaled_from_real <- function(real_df, n_samples = 500, n_features = 200,
                                  n_batches = 2, jitter_sd = 0.02, seed = 42) {
  feat_cols <- setdiff(names(real_df), BENCH_META_COLS)
  if (length(feat_cols) == 0) {
    stop("make_scaled_from_real: real_df has no feature columns.")
  }
  withr::with_seed(seed, {
    layout <- .bench_layout(n_samples, n_batches)
    n <- nrow(layout)

    # --- features: subsample (down) or tile (up) ---
    if (n_features <= length(feat_cols)) {
      chosen <- sample(feat_cols, n_features)
      out_names <- chosen
      src_idx <- match(chosen, feat_cols)
    } else {
      reps <- ceiling(n_features / length(feat_cols))
      src_idx <- rep(seq_along(feat_cols), reps)[seq_len(n_features)]
      dup_n <- ave(src_idx, src_idx, FUN = seq_along)
      out_names <- ifelse(dup_n == 1L, feat_cols[src_idx],
                          sprintf("%s_dup%d", feat_cols[src_idx], dup_n - 1L))
    }

    # --- rows: resample real rows, then jitter ---
    real_mat <- as.matrix(real_df[, feat_cols, drop = FALSE])
    row_pick <- sample(seq_len(nrow(real_mat)), n, replace = TRUE)
    sub <- real_mat[row_pick, src_idx, drop = FALSE]
    jitter <- matrix(stats::rnorm(length(sub), mean = 1, sd = jitter_sd),
                     nrow = nrow(sub))
    sub <- sub * pmax(jitter, 0.01)
    colnames(sub) <- out_names

    df <- cbind(
      data.frame(sample_name = sprintf("S%05d", seq_len(n)),
                 sample_type = layout$sample_type,
                 batch = layout$batch,
                 run_order = layout$run_order,
                 stringsAsFactors = FALSE),
      as.data.frame(sub, check.names = FALSE)
    )
    df
  })
}

# Write a shared table to disk and return its content hash (proves both
# engines consumed identical bytes).
write_shared_table <- function(df, path) {
  utils::write.csv(df, path, row.names = FALSE)
  if (requireNamespace("digest", quietly = TRUE)) {
    digest::digest(file = path, algo = "sha256")
  } else {
    NA_character_
  }
}
